150	    /**
151	     * Normalize the owner's supplied address into its canonical stored form, preferring
152	     * the structured fields over the flat address. When a non-blank {@code addressLine1}
153	     * is supplied it wins: both structured lines are normalized and the stored
154	     * {@code address} becomes their composed value; otherwise the flat {@code address} is
155	     * normalized and used. The owner is left with a normalized structured/flat address.
156	     *
157	     * @param owner the owner whose address fields are normalized in place
158	     * @return {@code true} if the owner supplies an address in either form, {@code false}
159	     * when neither a structured nor a flat address was given
160	     */
161	    private boolean normalizeAddress(Owner owner) {
162	        String addressLine1 = addressNormalizer.normalize(owner.getAddressLine1());
163	        String addressLine2 = addressNormalizer.normalize(owner.getAddressLine2());
164	        String flatAddress = addressNormalizer.normalize(owner.getAddress());
165	        owner.setAddressLine2(addressNormalizer.isBlank(addressLine2) ? null : addressLine2);
166	        if (!addressNormalizer.isBlank(addressLine1)) {
167	            owner.setAddressLine1(addressLine1);
168	            owner.setAddress(addressNormalizer.compose(addressLine1, addressLine2));
169	            return true;
170	        }
171	        owner.setAddressLine1(null);
172	        if (!addressNormalizer.isBlank(flatAddress)) {
173	            owner.setAddress(flatAddress);
