179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
182	        Owner replay = replayIdempotentCreate(idempotencyKey);
183	        if (replay != null) {
184	            return new ResponseEntity<>(ownerMapper.toOwnerDto(replay), HttpStatus.OK);
185	        }
186	        HttpHeaders headers = new HttpHeaders();
187	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
188	        if (!normalizeAddress(owner)) {
189	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
190	        }
191	        Optional<String> e164Telephone = telephoneNormalizer.toE164(owner.getTelephone());
192	        if (e164Telephone.isEmpty()) {
193	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
194	        }
195	        String telephone = e164Telephone.get();
196	        String email = emailNormalizer.normalize(owner.getEmail());
197	        if (email != null && (!emailNormalizer.isValid(email) || emailNormalizer.isDisposable(email))) {
198	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
199	        }
200	        if (owner.getPostcode() != null && !postcodeValidator.isValid(owner.getPostcode(), owner.getCity())) {
201	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
202	        }
203	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
204	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
205	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
206	        }
207	        LocalDate registrationDate = BusinessDay.rollForward(
208	            suppliedRegistrationDate == null ? LocalDate.now() : suppliedRegistrationDate);
209	        owner.setRegistrationDate(registrationDate);
210	        if (clinicService.countOwnersByRegistrationDate(registrationDate) >= MAX_OWNERS_PER_DAY) {
211	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
212	        }
213	        owner.setTelephone(telephone);
214	        owner.setEmail(email);
215	        if (clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
216	            return new ResponseEntity<>(HttpStatus.CONFLICT);
217	        }
218	        // Reject a hard duplicate: an existing live owner sharing this owner's identity key
219	        // (its normalized telephone, email and phonetic last name). The email-domain blocklist
220	        // above is applied first, so a disposable-email duplicate is a 400, not a 409.
221	        if (clinicService.isDuplicateOwner(owner)) {
222	            return new ResponseEntity<>(HttpStatus.CONFLICT);
223	        }
224	        // The household is keyed on (last name, postcode): a second owner sharing both joins
225	        // the existing household. Unless it declares 'sharesHousehold', it is recorded as a
226	        // possible duplicate of the sitting member (see saveOwner); a declared member joins as
227	        // a (non-suspected) household member instead. Either way its membership level is capped
228	        // relative to the household's existing members.
229	        owner.setDeclaredHouseholdMember(Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
230	        this.clinicService.saveOwner(owner);
231	        this.ownerAuditLogger.logCreated(owner);
232	        this.welcomeNotifier.welcome(owner);
233	        if (idempotencyKey != null) {
234	            this.idempotencyStore.remember(idempotencyKey, owner.getId());
235	        }
236	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
237	        headers.setLocation(UriComponentsBuilder.newInstance()
238	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
239	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
240	    }
