242	    /**
243	     * Look up the owner already created under the given {@code Idempotency-Key}, if any.
244	     * A repeated create carrying a key that has already produced an owner replays that
245	     * original owner instead of creating a duplicate.
246	     *
247	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when the
248	     *                       request carries no {@code Idempotency-Key} header
249	     * @return the originally created owner to replay, or {@code null} when the key is
250	     * absent, unseen, or its owner no longer exists
251	     */
252	    private Owner replayIdempotentCreate(String idempotencyKey) {
253	        if (idempotencyKey == null) {
254	            return null;
255	        }
256	        return idempotencyStore.findOwnerId(idempotencyKey)
257	            .map(clinicService::findOwnerById)
258	            .orElse(null);
259	    }
